tools.example:
// Inductor model: air box handled by the default Free Space node, core and winding overridden
model.component("comp1").physics("mf").feature("fsp1").selection().all();
model.component("comp1").physics("mf").create("als1", "AmperesLawSolid", 3);
model.component("comp1").physics("mf").feature("als1").selection().named("sel_core");

model.component("comp1").physics("es").create("scd1", "SpaceChargeDensity", 2);
model.component("comp1").physics("es").feature("scd1").selection().set(new int[]{1});
model.component("comp1").physics("es").feature("scd1").set("rhoq", "-e_const*semi.N");

// oxide gate represented analytically on the semiconductor side
model.component("comp1").physics("es").create("df1", "DisplacementField", 1);
model.component("comp1").physics("es").feature("df1").set("D0", new String[]{"0", "epsilon0_const*epsrOx*(Vg-V)/dOx", "0"});
